import Foundation
import Security

struct CTKIdentitySharedStore {
    let accessGroup = "group.ashi.cbaauth"
    let service = "ashi.com.newLearning.CBAAuthentication.ctk"
    let payloadAccount = "ctk.p12.payload"
    let passwordAccount = "ctk.p12.password"

    func loadIdentity() throws -> SecIdentity {
        let p12Data = try read(account: payloadAccount)
        let passwordData = try read(account: passwordAccount)
        guard let password = String(data: passwordData, encoding: .utf8) else {
            throw NSError(domain: "CTKIdentitySharedStore", code: -100, userInfo: [NSLocalizedDescriptionKey: "Invalid password encoding"])
        }

        var imported: CFArray?
        let status = SecPKCS12Import(
            p12Data as CFData,
            [kSecImportExportPassphrase as String: password] as CFDictionary,
            &imported
        )
        guard status == errSecSuccess,
              let array = imported as? [[String: Any]],
              let first = array.first,
              let identityAny = first[kSecImportItemIdentity as String] else {
            throw NSError(domain: "CTKIdentitySharedStore", code: Int(status), userInfo: [NSLocalizedDescriptionKey: "Failed to import shared p12"])
        }

        // SecIdentity is a CoreFoundation type; bridging cast will always succeed if the key exists
        let identity = identityAny as! SecIdentity
        return identity
    }

    private func read(account: String) throws -> Data {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecAttrAccessGroup as String: accessGroup,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        guard status == errSecSuccess, let data = result as? Data else {
            throw NSError(domain: "CTKIdentitySharedStore", code: Int(status), userInfo: [NSLocalizedDescriptionKey: "Missing shared keychain item for \(account)"])
        }
        return data
    }
}

import Foundation
import Security

struct CTKIdentitySharedStore {
    // Must match app + extension keychain-sharing entitlement entry exactly.
    let accessGroup = "S2ZMFGQM93.group.ashi.cbaauth"
    let service = "ashi.com.newLearning.CBAAuthentication.ctk"
    let payloadAccount = "ctk.p12.payload"
